/**
 * 검색(sparse/dense 벡터) 최적화 파싱.
 *
 * 원본 충실 파싱(blocksToMarkdown)과 별개로, 임베딩·BM25 검색에 맞춘 형태를 만든다.
 *  - 문단 내부 줄바꿈을 공백으로 정규화 → 한 문단 = 한 검색 단위
 *  - 섹션 경로(제N장 > 제N조 …)를 각 청크에 컨텍스트로 부착 → recall 향상
 *  - 표를 "헤더=값" 행으로 선형화 → 파이프/HTML 마크업 노이즈 제거
 *  - 제어문자/과다 공백 제거
 *  - 별표/별지서식 표는 LLM 요약을 덧붙일 수 있도록 needsSummary 표시
 *    (표 텍스트만으론 의미 검색 recall이 부족하므로)
 */

import type { IRBlock, IRTable } from "../types.js"

export interface SearchChunk {
  /** "text" = 본문 단락, "table" = 표(별표/별지서식 포함) */
  type: "text" | "table"
  /** 섹션 경로 (예: ["제2장 임원", "제5조(임원의 책무)"]) */
  headingPath: string[]
  /** 검색용 정규화 본문 */
  text: string
  /** 별표/별지서식 등 요약이 도움이 되는 표 여부 */
  needsSummary?: boolean
  /** LLM 요약 (summarizeChunks로 채워짐) */
  summary?: string
  pageNumber?: number
}

const reControl = /[�--]/g
const reByeolji = /별\s*표|별지\s*서식/

/** 텍스트 정규화: 제어문자 제거 + 내부 줄바꿈/연속공백 → 단일 공백 */
function normalize(text: string): string {
  return text.replace(reControl, "").replace(/\s+/g, " ").trim()
}

/** 표를 검색 친화적 행 텍스트로 선형화. 헤더가 있으면 "헤더=값"으로. */
export function linearizeTable(table: IRTable): string {
  const { cells, rows, cols } = table
  if (rows === 0 || cols === 0) return ""
  const cellText = (r: number, c: number) => normalize((cells[r]?.[c]?.text ?? "").replace(/<br\s*\/?>/gi, " "))

  // 헤더 행 후보 (hasHeader) + 다열 → "헤더=값" 형태
  if (table.hasHeader && cols >= 2 && rows >= 2) {
    const headers = Array.from({ length: cols }, (_, c) => cellText(0, c))
    const lines: string[] = []
    for (let r = 1; r < rows; r++) {
      const pairs: string[] = []
      for (let c = 0; c < cols; c++) {
        const v = cellText(r, c)
        if (!v) continue
        pairs.push(headers[c] ? `${headers[c]}=${v}` : v)
      }
      if (pairs.length) lines.push(pairs.join(", "))
    }
    if (lines.length) return lines.join("\n")
  }

  // 그 외: 각 행의 비어있지 않은 셀을 " | "로
  const lines: string[] = []
  for (let r = 0; r < rows; r++) {
    const vals: string[] = []
    for (let c = 0; c < cols; c++) { const v = cellText(r, c); if (v) vals.push(v) }
    if (vals.length) lines.push(vals.join(" | "))
  }
  return lines.join("\n")
}

/**
 * IRBlock[] → 검색 최적화 청크 배열 (LLM 없이, 동기).
 * heading을 만나면 해당 레벨로 섹션 경로를 갱신한다.
 */
export function toSearchChunks(blocks: IRBlock[]): SearchChunk[] {
  const chunks: SearchChunk[] = []
  const path: { level: number; text: string }[] = []

  const currentPath = () => path.map(p => p.text)

  for (const b of blocks) {
    if (b.type === "heading" && b.text) {
      const level = b.level ?? 1
      while (path.length && path[path.length - 1].level >= level) path.pop()
      path.push({ level, text: normalize(b.text) })
      continue
    }
    if (b.type === "table" && b.table) {
      const text = linearizeTable(b.table)
      if (!text) continue
      const hp = currentPath()
      const chunk: SearchChunk = { type: "table", headingPath: hp, text, pageNumber: b.pageNumber }
      if (hp.some(h => reByeolji.test(h)) || reByeolji.test(text.slice(0, 40))) chunk.needsSummary = true
      chunks.push(chunk)
      continue
    }
    if ((b.type === "paragraph" || b.type === "list") && b.text) {
      const text = normalize(b.text)
      if (!text) continue
      chunks.push({ type: "text", headingPath: currentPath(), text, pageNumber: b.pageNumber })
    }
  }
  return chunks
}

/**
 * 청크 → 단일 검색 텍스트. 각 청크는 빈 줄로 구분되어 청킹이 쉽고,
 * 섹션 경로가 머리에 붙어 컨텍스트를 보존한다.
 */
export function chunkToText(c: SearchChunk): string {
  const ctx = c.headingPath.length ? c.headingPath.join(" > ") + "\n" : ""
  const summary = c.summary ? `\n[요약] ${c.summary}` : ""
  return ctx + c.text + summary
}

/** IRBlock[] → 검색 최적화 단일 텍스트 (동기, LLM 없이). */
export function toSearchText(blocks: IRBlock[]): string {
  return toSearchChunks(blocks).map(chunkToText).join("\n\n")
}
